import Foundation

/// Wire shape for GraphJSON.encode. A private DTO layer rather than Codable conformance on
/// GraphNode/GraphEdge themselves: the schema needs kind/reason spelled out as fixed strings
/// (not Swift's enum case names, which the external HTML viewer must never depend on), and
/// thumbnailImageData has no field here at all -- structurally impossible to leak, not just
/// behaviorally suppressed.
private struct JSONNode: Encodable {
    let id: String
    let kind: String
    let name: String?
    let hasContactCard: Bool
    let isLive: Bool
    let degree: Int

    private enum CodingKeys: String, CodingKey {
        case id, kind, name, hasContactCard, isLive, degree
    }

    // Hand-written, not synthesized: the synthesized Encodable calls encodeIfPresent for an
    // Optional and would silently omit the key for a nil name, but the schema promises JSON
    // null. container.encode(_:forKey:) on an Optional is what actually emits null.
    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(id, forKey: .id)
        try container.encode(kind, forKey: .kind)
        try container.encode(name, forKey: .name)
        try container.encode(hasContactCard, forKey: .hasContactCard)
        try container.encode(isLive, forKey: .isLive)
        try container.encode(degree, forKey: .degree)
    }
}

private struct JSONEdge: Encodable {
    let a: String
    let b: String
    let reason: String
    let strength: Double
}

private struct JSONGraph: Encodable {
    let nodes: [JSONNode]
    let edges: [JSONEdge]
}

/// Prints a built Graph as JSON for an external HTML viewer (a separate effort in parallel,
/// not part of this package). Pure presentation over GraphBuilder's output: no graph logic
/// is reimplemented here, only a label mapping and a stable ordering for the wire format.
public enum GraphJSON {
    /// `guesses` defaults to empty so every existing call site (and GraphJSONTests' own
    /// fixtures) keeps encoding node.name verbatim, unchanged. When passed, an unnamed node's
    /// name is filled in from the cache via NodeLabel.resolve -- the exact same rule the
    /// screen and image export already use, tilde-prefix and all, so this JSON export can
    /// never disagree with what the app itself shows for the same node.
    public static func encode(graph: Graph, guesses: [String: NameGuess] = [:]) throws -> Data {
        // Sorted here, not just left to .sortedKeys below: .sortedKeys only orders the keys
        // within one node/edge object, not the position of elements in the nodes/edges
        // arrays, which otherwise reflects whatever order the caller happened to build the
        // Graph in. Two runs on unchanged data must be byte-identical.
        let nodes = graph.nodes
            .sorted { $0.id < $1.id }
            .map {
                JSONNode(
                    id: $0.id,
                    kind: kindLabel($0.kind),
                    name: NodeLabel.resolve(node: $0, guesses: guesses),
                    hasContactCard: $0.hasContactCard,
                    isLive: $0.isLive,
                    degree: $0.degree
                )
            }
        let edges = graph.edges
            .sorted { $0.id < $1.id }
            .map { JSONEdge(a: $0.nodeIDA, b: $0.nodeIDB, reason: reasonLabel($0.reason), strength: $0.strength) }

        let encoder = JSONEncoder()
        // Compact, not .prettyPrinted: this file is meant to be embedded in HTML.
        encoder.outputFormatting = [.sortedKeys]
        return try encoder.encode(JSONGraph(nodes: nodes, edges: edges))
    }

    // kindLabel/reasonLabel below have no default case on purpose: a new NodeKind or
    // EdgeReason member fails this file to compile until it is given a label here, instead
    // of silently falling through to nothing in the exported JSON.
    private static func kindLabel(_ kind: NodeKind) -> String {
        switch kind {
        case .user: return "user"
        case .person: return "person"
        case .group: return "group"
        }
    }

    private static func reasonLabel(_ reason: EdgeReason) -> String {
        switch reason {
        case .oneToOneThread: return "oneToOneThread"
        case .groupMembership: return "groupMembership"
        case .userGroupMembership: return "userGroupMembership"
        }
    }
}

import Foundation

/// A user's answer to one merge question: collapse the two people, or leave them separate
/// and never ask again.
public enum MergeDecision: String, Sendable, Equatable, Codable {
    case merged
    case separate
}

/// One answered merge question. identifierA/B are one normalized identifier from each side,
/// captured at answer time -- Person.id (the lexicographically smallest identifier) works for
/// this: identifiers only ever get ADDED to a person across a resync, never removed, so
/// today's Person.id remains a valid identifier of that same person forever, even after a
/// resync gives them a new, smaller one and reassigns the id. Canonicalized identifierA <
/// identifierB so a pair reads the same regardless of which side the UI happened to answer
/// from -- this canonicalization runs in this initializer, not at decode time, so it relies
/// on every MergeAnswer having been constructed through here at least once before being saved.
public struct MergeAnswer: Sendable, Equatable, Codable {
    public let identifierA: String
    public let identifierB: String
    public let decision: MergeDecision

    public init(identifierA: String, identifierB: String, decision: MergeDecision) {
        if identifierA <= identifierB {
            self.identifierA = identifierA
            self.identifierB = identifierB
        } else {
            self.identifierA = identifierB
            self.identifierB = identifierA
        }
        self.decision = decision
    }
}

/// Schema slot for the step 7 model pass cache (unnamed-handle name guessing), deliberately
/// unpopulated by this step: included here so the on-disk format is settled now rather than
/// migrated later.
public struct NameGuess: Sendable, Equatable, Codable {
    public let name: String
    public let detail: String?

    public init(name: String, detail: String? = nil) {
        self.name = name
        self.detail = detail
    }
}

/// The user's saved curation: everything that must survive a resync (PLAN.md, build order
/// step 8). Keyed throughout by normalized identifier or chat guid, never by a database row
/// id or Person.id alone -- both renumber across a resync, identifiers and guids do not.
public struct Overrides: Sendable, Equatable, Codable {
    public var hiddenPersonIdentifiers: Set<String>
    public var hiddenGroupGUIDs: Set<String>
    public var removedPersonIdentifiers: Set<String>
    public var mergeAnswers: [MergeAnswer]
    public var nameGuesses: [String: NameGuess]

    public init(
        hiddenPersonIdentifiers: Set<String> = [],
        hiddenGroupGUIDs: Set<String> = [],
        removedPersonIdentifiers: Set<String> = [],
        mergeAnswers: [MergeAnswer] = [],
        nameGuesses: [String: NameGuess] = [:]
    ) {
        self.hiddenPersonIdentifiers = hiddenPersonIdentifiers
        self.hiddenGroupGUIDs = hiddenGroupGUIDs
        self.removedPersonIdentifiers = removedPersonIdentifiers
        self.mergeAnswers = mergeAnswers
        self.nameGuesses = nameGuesses
    }

    private enum CodingKeys: String, CodingKey {
        case hiddenPersonIdentifiers, hiddenGroupGUIDs, removedPersonIdentifiers, mergeAnswers, nameGuesses
    }

    // Hand-written, not synthesized: every field decodes with decodeIfPresent so a file
    // written before a field existed (or a stripped-down hand edit) still loads instead of
    // throwing, and a future field can be added the same way without breaking old files.
    // Encoding is still the compiler-synthesized Encodable, generated from CodingKeys plus
    // these same stored properties.
    // Hand-written, not synthesized: every field decodes with decodeIfPresent so a file
    // written before a field existed (or a stripped-down hand edit) still loads instead of
    // throwing, and a future field can be added the same way without breaking old files.
    // Encoding is still the compiler-synthesized Encodable, generated from CodingKeys plus
    // these same stored properties.
    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        hiddenPersonIdentifiers = try container.decodeIfPresent(Set<String>.self, forKey: .hiddenPersonIdentifiers) ?? []
        hiddenGroupGUIDs = try container.decodeIfPresent(Set<String>.self, forKey: .hiddenGroupGUIDs) ?? []
        removedPersonIdentifiers = try container.decodeIfPresent(Set<String>.self, forKey: .removedPersonIdentifiers) ?? []
        mergeAnswers = try container.decodeIfPresent([MergeAnswer].self, forKey: .mergeAnswers) ?? []
        nameGuesses = try container.decodeIfPresent([String: NameGuess].self, forKey: .nameGuesses) ?? [:]
    }
}

import Foundation

/// Derives person-to-person acquaintance edges from the built graph's group-chat activity
/// (PLAN.md, "The acquaintance layer"). Runs entirely over GroupChatActivity -- no database
/// read, no message text -- so it can run on every rebuild as cheaply as GraphBuilder itself.
public enum AcquaintanceDerivation {
    private struct PairKey: Hashable {
        let a: String
        let b: String
    }

    public static func derive(
        groupChatActivity: [GroupChatActivity],
        fullyAcquaintedRosterKeys: Set<[String]>
    ) -> [Acquaintance] {
        // Every chat with 2+ resolved members contributes base weight to EVERY pair among its
        // roster, so a pair sharing at least one chat always gets a scoreByPair entry, even a
        // lurker pair or one that ends up below the likely floor -- the tier decision below is
        // what turns "has a score" into "appears in the export", not this accumulation step.
        var scoreByPair: [PairKey: Double] = [:]
        var evidenceByPair: [PairKey: [AcquaintanceEvidence]] = [:]
        // Every pair among a marked chat's FULL roster must promote to confirmed, including a
        // pair whose chats are otherwise all sub-threshold -- collected separately from
        // scoreByPair so marking never depends on what score happened to accumulate.
        var confirmedPairs: Set<PairKey> = []

        for chatActivity in groupChatActivity {
            let members = chatActivity.roster.sorted()
            guard members.count >= 2 else { continue } // a real group node always has 2+; defensive only
            let n = members.count
            let baseWeight = 1.0 / Double(n - 1)
            let isMarked = fullyAcquaintedRosterKeys.contains(AcquaintanceRosterKey.canonicalize(chatActivity.roster))

            for i in 0..<members.count {
                for j in (i + 1)..<members.count {
                    let personA = members[i]
                    let personB = members[j]
                    let key = PairKey(a: personA, b: personB) // members is sorted, so a < b already

                    let daysA = chatActivity.activeDaysByPersonID[personA] ?? []
                    let daysB = chatActivity.activeDaysByPersonID[personB] ?? []
                    let coActiveDays = daysA.intersection(daysB).count
                    let cappedDays = min(coActiveDays, AcquaintanceScoring.coActiveDayCapPerChat)
                    let contribution = baseWeight + Double(cappedDays) * AcquaintanceScoring.coActiveDayWeight

                    scoreByPair[key, default: 0] += contribution
                    evidenceByPair[key, default: []].append(
                        AcquaintanceEvidence(
                            chatId: chatActivity.chatId,
                            chatName: chatActivity.name,
                            memberCount: n,
                            coActiveDays: coActiveDays // raw, uncapped: a fact, not a scoring input
                        )
                    )
                    if isMarked {
                        confirmedPairs.insert(key)
                    }
                }
            }
        }

        var result: [Acquaintance] = []
        for (key, score) in scoreByPair {
            let tier: AcquaintanceTier
            if confirmedPairs.contains(key) {
                tier = .confirmed
            } else if score >= AcquaintanceScoring.strongThreshold {
                tier = .strong
            } else if score >= AcquaintanceScoring.likelyThreshold {
                tier = .likely
            } else {
                continue // below likely and never marked: no acquaintance edge recorded (PLAN.md)
            }

            let evidence = (evidenceByPair[key] ?? []).sorted { $0.chatId < $1.chatId }
            result.append(Acquaintance(a: key.a, b: key.b, tier: tier, score: score, evidence: evidence))
        }

        // scoreByPair is a Dictionary (unordered iteration); sort here so the same input always
        // yields the same output order, independent of hashing -- GraphJSON's own determinism
        // requirement depends on this, not just its own field-level sorting.
        return result.sorted { $0.a != $1.a ? $0.a < $1.a : $0.b < $1.b }
    }
}

import Foundation

/// The durable identity of a group chat for the "everyone here knows each other" marker
/// (PLAN.md, "The acquaintance layer"): the chat's resolved member identifiers, sorted and
/// deduplicated. Never the chat guid or a row id -- both renumber and re-split across a
/// resync (a service-split merge can even change which guid is smallest), but the people
/// sharing the chat do not, so keying on them is what lets a marking survive both.
public enum AcquaintanceRosterKey {
    /// One identifier per resolved member (Person.id): canonicalized by sorting so the pair
    /// "A,B" and "B,A" key the same, and by deduplicating so a caller passing a Set or an
    /// Array with repeats still gets one canonical key either way.
    public static func canonicalize<S: Sequence>(_ identifiers: S) -> [String] where S.Element == String {
        Array(Set(identifiers)).sorted()
    }
}

